class Solution:
    def minInsertions(self, s: str) -> int:
        n = len(s)
        s_rev = s[::-1]
        # 求 s 和 s_rev 的 LCS（滚动数组优化）
        prev = [0] * (n + 1)
        curr = [0] * (n + 1)
        for i in range(1, n + 1):
            for j in range(1, n + 1):
                if s[i-1] == s_rev[j-1]:
                    curr[j] = prev[j-1] + 1
                else:
                    curr[j] = max(prev[j], curr[j-1])
            prev, curr = curr, [0] * (n + 1)
        return n - prev[n]
